/* Original SVG teaching illustrations. Only Compton kinematics is quantitative.
   Animation times, counts, tracks and molecular motion are illustrative. */
(()=>{'use strict';
const M=window.LinacTissue,$=id=>document.getElementById(id),cl=M.clamp,starts=M.starts,duration=M.duration;
const C={ph:'#f4cf83',el:'#8be7e9',rad:'#f4a9cc',muted:'#a8bfce',line:'#47657a'};
const scenes=[
 {nav:'Feld im Gewebe',kind:'IM GEWEBE',visual:'Ein Feld. Viele mögliche Wege.',scale:'Gewebe → ausgewähltes Einzelereignis',detail:'Ein Ereignis vergrößern',title:'Das Feld endet nicht am Ziel',text:'Das geformte Photonenfeld tritt in den Körper ein. Ein Photon kann den gezeigten Ausschnitt ohne Wechselwirkung durchqueren. Bei einer Compton-Streuung überträgt es einen Teil seiner Energie auf ein Elektron und fliegt mit veränderter Richtung und geringerer Energie weiter.',take:'Energieübertragung findet auch in Normalgewebe statt. Photonen erkennen keine Tumorgrenze.',question:'Ist die gelbe Feldkontur eine Dosisgrenze?',answer:'Nein. Sie markiert hier nur ausgewählte direkte Strahlrichtungen. Streuphotonen und Sekundärelektronen können Energie außerhalb dieser Kontur transportieren. Die Zahl der gezeichneten Spuren gibt keine Wahrscheinlichkeiten an.',caption:'Anschluss an das geformte Feld aus Phase 02. Ausgewählte Wege, vergrößerte Zellsymbole und geometrische Feldgrenzen – kein Dosisbild.',note:'Der Ring markiert ein Compton-Beispiel. In der nächsten Ansicht trennen wir das weiterfliegende Photon vom herausgelösten Elektron.',source:'Schlegel et al. (2018), Kap. 1.3.2.4 · Krieger (2009), Kap. 11.2'},
 {nav:'Energie übertragen',kind:'COMPTON & ELEKTRONENSPUR',visual:'Ein Photon gibt einen Teil ab.',scale:'Einzelereignis → Ausschnitt einer Elektronenspur',detail:'Danach: viele kleine Überträge',title:'Das Elektron trägt Energie weiter',text:'Beim Comptoneffekt entstehen ein gestreutes Photon und ein Rückstoßelektron. Das Elektron gibt entlang seines Weges Energie durch Anregungen und Ionisationen ab. Bei einer Ionisation wird ein weiteres Elektron freigesetzt; bei einer Anregung bleibt es zunächst gebunden.',take:'Der Compton-Ort ist der Start einer Elektronenspur. Die übertragene Energie wird nicht vollständig an einem einzigen Punkt deponiert.',question:'Was ändert sich bei größerem Photonen-Streuwinkel?',answer:'Für dieselbe einfallende Energie erhält das Elektron in diesem Einzelereignis mehr kinetische Energie; das gestreute Photon behält weniger. Die Winkel sind über die Impulserhaltung gekoppelt. Daraus folgt noch keine Auftretenswahrscheinlichkeit für diesen Winkel.',caption:'Freies Elektron, anfangs in Ruhe. Die Winkel und Energien sind gekoppelt berechnet; Längen und Teilchengrößen bleiben symbolisch.',note:'Türkis: ausgewählte Elektronenspur. Ein abgehendes e⁻ kennzeichnet Ionisation; ein goldener Ring eine Anregung ohne Elektronenaustritt. Keine berechnete Reichweite oder Dosis.',source:'Schlegel et al. (2018), Kap. 1.3.1 / 1.3.2.4, S. 14–15'},
 {nav:'Wasser reagiert',kind:'WASSERRADIOLYSE',visual:'Vom Wasser zur reaktiven Spezies.',scale:'Molekulare Nachbarschaft · neuer Raum- und Zeitmaßstab',detail:'Drei unterschiedliche Vorgänge',title:'Physik wird Chemie',text:'Ein Elektron kann ein Wassermolekül ionisieren. Das entstehende Wasser-Radikalkation überträgt ein Proton auf ein benachbartes Wassermolekül; dabei entstehen H₃O⁺ und •OH. Freigesetzte Elektronen können nach weiteren Energieverlusten hydratisiert werden.',take:'Der Punkt • steht für ein ungepaartes Elektron. Das Zeichen + oder − steht für elektrische Ladung.',question:'Sind ein Radikal und ein Ion dasselbe?',answer:'Nein. •OH ist ein neutrales Radikal; OH⁻ ist ein negativ geladenes Hydroxidion ohne ungepaartes Elektron. H₂O⁺• besitzt sowohl eine positive Ladung als auch ein ungepaartes Elektron. Das hydratisierte Elektron e⁻aq ist eine weitere reaktive Spezies.',caption:'Ausgewählte Schritte in flüssigem Wasser. Kugeln sind Atomsymbole; Bindungen, Abstände und Zeitverlauf sind veranschaulicht.',note:'Die drei Teilschritte zeigen unterschiedliche Zustände. Die Hydratation folgt nach dem Abbremsen des betrachteten Elektrons, nicht als Hülle um ein noch hochenergetisches Elektron.',source:'Krieger (2009), Kap. 11.2, S. 381–385 · IAEA 2.2.7.2 · IUPAC: radical'},
 {nav:'Reaktionen konkurrieren',kind:'CHEMISCHE FOLGEREAKTIONEN',visual:'Der Reaktionspartner entscheidet.',scale:'Lokale molekulare Umgebung · ausgewählte Reaktionswege',detail:'Ähnliches Zeichen, andere Spezies',title:'Kein vorbestimmtes Zellschicksal',text:'Ein Hydroxylradikal kann mit einem organischen Molekül reagieren und ihm ein Wasserstoffatom entziehen. Ein neuer Radikalort entsteht am organischen Rest. Treffen dagegen zwei Hydroxylradikale aufeinander, können sie Wasserstoffperoxid bilden.',take:'Welche Reaktion abläuft, hängt von den Partnern in der Umgebung ab. Eine chemische Veränderung allein legt die Zellfolge noch nicht fest.',question:'Ist Rekombination automatisch die Rückkehr zu harmlosem Wasser?',answer:'Nein. Im gezeigten Beispiel entsteht H₂O₂: kein Radikal, aber weiterhin chemisch wirksam. Auch Reaktionen mit Radikalfängern und Sauerstoff sind möglich. Ob eine Zellfunktion dauerhaft ausfällt, hängt unter anderem von Zielstruktur, Schadensart und Reparatur ab – Thema der nächsten Phase.',caption:'Zwei alternative Beispiele; die Auswahl legt keine Wahrscheinlichkeit fest. R steht für einen organischen Rest, nicht speziell für DNA.',note:'•OH: Hydroxylradikal. OH⁻: Hydroxidion. H₂O₂: Wasserstoffperoxid. Die drei Schreibweisen bezeichnen unterschiedliche chemische Spezies.',source:'Krieger (2009), Kap. 11.2, S. 384–385 · IAEA 2.2.7.2–3 · IUPAC: radical'}
];
let time=0,playing=false,last=0,frame=0,current=-1,raf=0,energy=1,angle=60,reaction='abstraction';
const num=x=>Number(x).toFixed(2),lerp=(a,b,q)=>a+(b-a)*q;
const txt=(x,y,s,c=C.muted,size=18,extra='')=>`<text x="${num(x)}" y="${num(y)}" fill="${c}" font-size="${size}" ${extra}>${s}</text>`;
const line=(x,y,a,b,c=C.line,w=2,extra='')=>`<line x1="${num(x)}" y1="${num(y)}" x2="${num(a)}" y2="${num(b)}" stroke="${c}" stroke-width="${w}" ${extra}/>`;
const circle=(x,y,r,fill,extra='')=>`<circle cx="${num(x)}" cy="${num(y)}" r="${num(r)}" fill="${fill}" ${extra}/>`;
const path=ps=>'M'+ps.map(p=>p.map(num).join(',')).join('L');
const ann=s=>`<g class="annotation">${s}</g>`;
const defs=`<defs><radialGradient id="oxygen" cx=".32" cy=".25" r=".8"><stop stop-color="#f4c9c8"/><stop offset=".3" stop-color="#dc8a9b"/><stop offset="1" stop-color="#693b59"/></radialGradient><radialGradient id="hydrogen" cx=".3" cy=".25"><stop stop-color="#fff"/><stop offset=".55" stop-color="#bdcdd5"/><stop offset="1" stop-color="#57758c"/></radialGradient><radialGradient id="cell"><stop stop-color="#344c60" stop-opacity=".42"/><stop offset=".8" stop-color="#304b60" stop-opacity=".28"/><stop offset="1" stop-color="#65849c" stop-opacity=".5"/></radialGradient><radialGradient id="nucleus"><stop stop-color="#827ca0"/><stop offset=".7" stop-color="#45546f"/><stop offset="1" stop-color="#283b50"/></radialGradient><linearGradient id="steel"><stop stop-color="#2f4859"/><stop offset=".4" stop-color="#b2c4c9"/><stop offset=".6" stop-color="#78909e"/><stop offset="1" stop-color="#293e50"/></linearGradient><radialGradient id="electronGlow"><stop stop-color="#8be7e9" stop-opacity=".3"/><stop offset="1" stop-color="#8be7e9" stop-opacity="0"/></radialGradient></defs>`;
function electron(x,y,label=true){return circle(x,y,15,'url(#electronGlow)')+circle(x,y,5,C.el,'data-electron="free"')+ (label?txt(x+12,y-11,'e⁻',C.el,18):'');}
function photon(x,y,rotation=0){return `<g class="photon-symbol" transform="translate(${num(x)} ${num(y)}) rotate(${num(rotation)})"><path d="M-17 0Q-12-10-7 0T3 0T13 0" fill="none" stroke="${C.ph}" stroke-width="3"/>${circle(17,0,3,C.ph)}</g>`;}
function atom(x,y,k,scale=1){const r=(k==='O'?23:14)*scale;return circle(x+2,y+4,r,'#030b12','opacity=".3"')+circle(x,y,r,`url(#${k==='O'?'oxygen':'hydrogen'})`,`stroke="#d7dce5" stroke-opacity=".25" data-atom="${k}"`)+txt(x,y+5*scale,k,k==='O'?'#321b34':'#183343',15*scale,'text-anchor="middle" font-weight="650"');}
function bond(x,y,a,b){return line(x,y,a,b,'#40556b',9,'stroke-linecap="round"')+line(x,y,a,b,'#a2b5c3',4,'stroke-linecap="round"');}
function water(x,y,rot=0,s=1,mark=''){let h=bond(0,0,-39,30)+bond(0,0,39,30)+atom(0,0,'O')+atom(-39,30,'H')+atom(39,30,'H');if(mark)h+=txt(24,-28,mark,C.rad,26);return `<g transform="translate(${x} ${y}) rotate(${rot}) scale(${s})">${h}</g>`;}
function hydroxyl(x,y,flip=1,dot=true){return bond(x,y,x-39*flip,y+30*flip)+atom(x,y,'O')+atom(x-39*flip,y+30*flip,'H')+(dot?circle(x+23*flip,y-20*flip,5,C.rad):'');}
function cell(x,y,s=1,rot=0){let h=`<ellipse rx="51" ry="42" fill="url(#cell)" stroke="#68859a" stroke-width="1.7"/><ellipse rx="47" ry="38" fill="none" stroke="#597286" stroke-opacity=".5"/><ellipse cx="-10" cy="-2" rx="18" ry="15" fill="url(#nucleus)" stroke="#8795aa" stroke-opacity=".5"/>`;for(let i=0;i<4;i++){const a=i*1.5;h+=`<ellipse cx="${28*Math.cos(a)}" cy="${25*Math.sin(a)}" rx="9" ry="4" transform="rotate(${i*22})" fill="#8e8c99" opacity=".35"/>`;}h+=`<path d="M-15-5q10-10 15 1t-8 8" fill="none" stroke="#a8a2b4" opacity=".35"/>`;return `<g transform="translate(${x} ${y}) rotate(${rot}) scale(${s})">${h}</g>`;}
function backdrop(){let h='';for(let i=0;i<22;i++){const x=35+(i*113)%565,y=55+(i*71)%355;h+=circle(x,y,1.4,'#8ba4ba','opacity=".22"');}return h;}
function field(){let h=defs+backdrop();
 h+=`<path d="M85 142L520 142L575 180V441H140L85 403Z" fill="#182c3d" stroke="#49647b"/><path d="M85 142L140 180H575M140 180V441M520 142V403L575 441M85 403H520" fill="none" stroke="#314c64"/>`;
 h+=`<path d="M270 82L212 435H408L350 82Z" fill="${C.ph}" opacity=".035"/>`+line(270,82,212,435,C.ph,1,'stroke-dasharray="5 7" opacity=".6"')+line(350,82,408,435,C.ph,1,'stroke-dasharray="5 7" opacity=".6"');
 for(let r=0;r<3;r++)for(let c=0;c<4;c++)h+=cell(185+c*91+(r%2)*12,205+r*85,.82,(c-r)*12);
 h+=`<path d="M205 26H415L400 60H220Z" fill="url(#steel)" stroke="#8fa6b5"/>`+line(203,77,270,77,'#a7b9c1',11)+line(350,77,417,77,'#a7b9c1',11);
 h+=ann(txt(27,52,'MLC-Ausgang',C.muted,18)+line(175,48,211,48)+txt(25,118,'Geformtes Feld',C.ph,18)+line(178,113,250,113));
 const q=cl(time/16),paths=[[[280,88],[236,452]],[[310,88],[310,250],[530,400]],[[338,88],[379,452]]];
 paths.forEach((ps,i)=>{h+=`<path d="${path(ps)}" fill="none" stroke="${C.ph}" stroke-width="1.8" opacity="${q>.1?.45:.16}"/>`;const p=M.pointOnTrack(ps,cl((q-i*.13)*1.25));let a=i===1&&q>.53?34:90;h+=photon(p[0],p[1],a);});
 if(q>.49){const epts=[[310,250],[314,277],[337,285],[345,315],[368,326],[360,347]];h+=`<path d="${path(epts)}" fill="none" stroke="${C.el}" stroke-width="2"/>`;const ep=M.pointOnTrack(epts,cl((q-.49)*2.2));h+=electron(...ep)+circle(310,250,27,'none',`stroke="${C.el}" stroke-dasharray="4 5"`);}
 h+=ann(txt(420,112,'Kein Dosisbild',C.muted,16));
 $('tissue').innerHTML=h;
 $('detail').innerHTML=cell(190,125,1.8,0)+line(22,115,235,115,C.ph,2)+line(235,115,353,45,C.ph,2)+`<path d="M235 115Q270 142 270 166T310 213" fill="none" stroke="${C.el}" stroke-width="2"/>`+photon(85,115)+photon(306,79,-27)+electron(294,197)+circle(235,115,19,'none',`stroke="${C.el}" stroke-dasharray="3 4"`)+ann(txt(20,246,'Photon + Elektron getrennt verfolgen',C.muted,17));
}
function compton(){const v=M.compton(energy,angle),q=cl((time-23)/9),cx=290,cy=225,L=195,ex=cx+Math.cos(v.phi)*190,ey=cy+Math.sin(v.phi)*190,px=cx+Math.cos(v.theta)*L,py=cy-Math.sin(v.theta)*L;let h=defs+backdrop();
 h+=circle(cx,cy,175,'#1a3042','opacity=".4"')+circle(cx,cy,175,'none','stroke="#49677c" stroke-dasharray="3 9" opacity=".4"');
 h+=line(35,cy,545,cy,'#537085',1,'stroke-dasharray="4 6"')+ann(txt(28,200,'Einfallendes Photon γ',C.ph,18));
 h+=line(45,cy,cx,cy,C.ph,2);if(q===0)h+=electron(cx,cy);if(q===0)h+=photon(lerp(55,cx,cl((time-20)/3)),cy);
 if(q>0){h+=line(cx,cy,px,py,C.ph,2.5)+line(cx,cy,ex,ey,C.el,2.5)+photon(lerp(cx,px,q),lerp(cy,py,q),-angle)+electron(lerp(cx,ex,q),lerp(cy,ey,q));h+=circle(cx,cy,10,'none',`stroke="#d4e4ea"`);}
 const ax=cx+62*Math.cos(v.theta),ay=cy-62*Math.sin(v.theta);h+=`<path d="M${cx+62} ${cy}A62 62 0 0 0 ${ax} ${ay}" fill="none" stroke="${C.ph}" stroke-width="2"/>`;
 h+=ann(txt(cx+72,cy-14,`θ = ${angle}°`,C.ph,18)+txt(25,55,'Gestreutes Photon γ′',C.ph,18)+txt(330,443,'Rückstoßelektron e⁻',C.el,18)+txt(30,465,'Winkel gekoppelt · Weglängen symbolisch',C.muted,16));
 $('tissue').innerHTML=h;
 const pts=[[24,82],[92,103],[157,85],[200,137],[255,128],[291,178],[338,198],[350,237]],p=cl((time-29)/14),ep=M.pointOnTrack(pts,p);let d=`<path d="${path(pts)}" fill="none" stroke="${C.el}" stroke-width="2.3" opacity=".55"/>`;
 [[92,103],[200,137],[291,178]].forEach(([x,y],i)=>{const active=p>[.14,.43,.71][i];d+=circle(x,y,18,'#244356',`stroke="${active?(i===1?C.ph:C.rad):'#527084'}"`);if(active&&i!==1){d+=line(x,y,x+27,y-42,C.el,1.5)+electron(x+27,y-42);d+=txt(x-18,y+5,'+',C.rad,17);}if(active&&i===1)d+=circle(x,y,24,'none',`stroke="${C.ph}"`);});
 d+=electron(...ep)+ann(txt(15,29,'Ionisation',C.rad,18)+txt(191,68,'Anregung',C.ph,18)+line(203,76,201,110,C.ph,1)+txt(15,264,'Nur ausgewählte Ereignisse einer Spur',C.muted,16));$('detail').innerHTML=d;
 ['incomingEnergy','outgoingEnergy','electronEnergy'].forEach((id,i)=>$(id).textContent=[v.energy,v.photon,v.electron][i].toFixed(3).replace('.',','));$('angleValue').textContent=angle+'°';
}
function chemistry(){const {step,progress:q}=M.chemistry(time);let h=defs+backdrop(),d='';
 document.querySelectorAll('[data-chem]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.chem)===step)));
 if(step===0){const hit=q>.51;h+=water(310,242,0,1.4,hit?'+•':'');h+=line(55,235,551,264,C.el,1.5,'stroke-dasharray="4 7" opacity=".5"');h+=electron(lerp(60,550,q),lerp(235,264,q));if(hit){h+=line(310,242,420,119,C.el,1.5,'opacity=".6"')+electron(lerp(310,420,cl((q-.51)/.49)),lerp(242,119,cl((q-.51)/.49)));}h+=ann(txt(45,176,'Energieübertrag durch e⁻',C.el,19)+txt(335,70,'Freigesetztes e⁻',C.el,19)+txt(208,356,hit?'Wasser-Radikalkation':'Wassermolekül',C.muted,20));
  equation('IONISATION DURCH EIN ELEKTRON','H₂O + e⁻<sub>ein</sub> → H₂O⁺• + e⁻<sub>aus</sub> + e⁻<sub>sek</sub>','Das einfallende Elektron gibt Energie ab und bleibt erhalten. Ein weiteres Elektron wird aus dem Wassermolekül freigesetzt.');
  d=txt(20,36,'Ein Elektron fehlt im Molekül.',C.muted,19)+circle(80,119,34,'#243b50')+txt(80,129,'+',C.rad,32,'text-anchor="middle"')+txt(137,116,'positive Ladung',C.muted,18)+circle(80,205,34,'#243b50')+circle(80,205,6,C.rad)+txt(137,201,'ungepaartes Elektron',C.muted,18);
 }else if(step===1){const hx=lerp(224,445,q),hy=lerp(250,166,q);h+=bond(185,220,146,250)+atom(185,220,'O')+atom(146,250,'H');if(q<.25)h+=line(185,220,hx,hy,'#a2b5c3',4,'stroke-dasharray="4 5"');if(q>.75)h+=line(445,220,hx,hy,'#a2b5c3',4);h+=water(445,220)+atom(hx,hy,'H')+circle(207,194,5,C.rad)+txt(lerp(220,475,q),176,'+',C.rad,29);h+=ann(txt(74,339,q>.9?'Hydroxylradikal •OH':'Wasser-Radikalkation',C.rad,18)+txt(375,339,q>.9?'Oxoniumion H₃O⁺':'Nachbarwasser',C.muted,18)+txt(238,80,'Ein Proton wird übertragen.',C.muted,20));h+=`<path d="M230 130Q335 75 421 130" fill="none" stroke="#a4b8c8" stroke-dasharray="5 6"/>`+ann(txt(303,104,'H⁺',C.rad,22));
  equation('PROTONTRANSFER AN EIN NACHBARMOLEKÜL','H₂O⁺• + H₂O → H₃O⁺ + •OH','Es wird ein Proton übertragen. Das ungepaarte Elektron bleibt am entstehenden Hydroxylradikal. Gesamtladung: vorher +1, nachher +1.');
  d=water(114,108,0,.9,'+•')+txt(215,122,'→',C.muted,30)+txt(215,84,'H⁺',C.rad,21)+hydroxyl(306,108,1,true)+txt(43,210,'Radikal und Ladung können',C.muted,19)+txt(43,239,'auf verschiedene Produkte übergehen.',C.muted,17);
 }else{h+=circle(320,220,80,'url(#electronGlow)')+circle(320,220,44,'none','stroke="#8be7e9" stroke-dasharray="4 6" opacity=".6"')+electron(320,220,false)+txt(320,173,'e⁻aq',C.el,26,'text-anchor="middle"');for(let i=0;i<5;i++){const a=i*2*Math.PI/5,r=lerp(170,126,q);h+=water(320+Math.cos(a)*r,220+Math.sin(a)*r,a*180/Math.PI+90,.64);}h+=ann(txt(116,424,'Wasser richtet sich um das Elektron aus.',C.muted,20));
  equation('NACH DEM ABBREMSEN: HYDRATATION','e⁻<sub>langsam</sub> → e⁻<sub>aq</sub>','Wassermoleküle stabilisieren das Elektron in einer Lösungsmittelumgebung. „aq“ bezeichnet den hydratisierten Zustand; die gezeichnete Hülle hat keine feste Molekülzahl.');
  d=electron(61,66)+txt(105,72,'weitere Energieverluste',C.muted,18)+line(69,94,69,160,C.line,2)+circle(69,204,40,'url(#electronGlow)')+circle(69,204,25,'none','stroke="#8be7e9" stroke-dasharray="3 5"')+electron(69,204,false)+txt(125,211,'hydratisiertes Elektron',C.el,18);
 }
 $('visualTitle').textContent=['1 · Wasser ionisieren.','2 · Ein Proton wechselt den Partner.','3 · Das Elektron wird hydratisiert.'][step];$('tissue').innerHTML=h;$('detail').innerHTML=d;
}
function organic(x,y,radical){let h='';for(let i=0;i<4;i++){h+=line(x+i*28,y+(i%2)*20,x+(i+1)*28,y+((i+1)%2)*20,'#a4bad0',7);h+=circle(x+i*28,y+(i%2)*20,17,'#4b657d','stroke="#91a6bb"');}h+=circle(x+112,y,17,'#4b657d','stroke="#91a6bb"')+txt(x+53,y+70,'R',C.muted,28);if(radical)h+=circle(x-17,y-18,5,C.rad);return h;}
function reactions(){const q=cl((time-78)/15);let h=defs+backdrop();if(reaction==='abstraction'){const hx=lerp(374,224,q),hy=lerp(220,250,q);h+=hydroxyl(185,220,1,q<.96)+organic(420,220,q>.96);if(q<.3)h+=bond(420,220,hx,hy);if(q>.7)h+=bond(185,220,hx,hy);h+=atom(hx,hy,'H')+ann(txt(115,342,q>.96?'Wasser H₂O':'Hydroxylradikal •OH',C.muted,20)+txt(366,342,q>.96?'Organischer Rest R•':'Biomolekül RH',C.muted,19)+txt(123,91,'Ein Wasserstoffatom wird entzogen.',C.muted,21));
 equation('MÖGLICHKEIT A · WASSERSTOFFABSTRAKTION','•OH + RH → H₂O + R•','Ein H-Atom wird übertragen. Der Radikalort wandert auf den organischen Rest. R bezeichnet hier einen Teil eines Biomoleküls.');
 }else{const ax=lerp(175,285,q),bx=lerp(465,345,q);if(q>.85)h+=bond(ax,220,bx,220);h+=hydroxyl(ax,220,1,q<.96)+hydroxyl(bx,220,-1,q<.96)+ann(txt(134,89,'Zwei Radikale können rekombinieren.',C.muted,21)+txt(320,346,q>.96?'Wasserstoffperoxid H₂O₂':'Zwei Hydroxylradikale',C.muted,22,'text-anchor="middle"'));equation('MÖGLICHKEIT B · REKOMBINATION','•OH + •OH → H₂O₂','Zwei Hydroxylradikale bilden Wasserstoffperoxid. Es besitzt kein ungepaartes Elektron, ist aber weiterhin chemisch wirksam.');}
 h+=ann(txt(320,434,'Keine Häufigkeits- oder Reaktionsratenberechnung',C.muted,17,'text-anchor="middle"'));$('tissue').innerHTML=h;
 let d='';[['•OH','Radikal · neutral',C.rad],['OH⁻','Ion · kein Radikal',C.el],['H₂O₂','Molekül · kein Radikal',C.muted]].forEach(([sym,s,col],i)=>{const y=40+i*88;d+=`<rect x="10" y="${y-29}" width="380" height="72" rx="7" fill="#152a3c" stroke="#354f65"/>`+txt(28,y+13,sym,col,28)+txt(140,y+9,s,C.muted,17);});$('detail').innerHTML=d;
}
function equation(label,eq,note){$('equationLabel').textContent=label;$('equation').innerHTML=eq;$('equationNote').textContent=note;}
function clock(t){return String(Math.floor(t/60)).padStart(2,'0')+':'+String(Math.floor(t%60)).padStart(2,'0');}
function render(){const n=M.scene(time),s=scenes[n];if(n!==current){current=n;$('sceneKind').textContent=`0${n+1} / ${s.kind}`;$('sceneLabel').textContent=`0${n+1} / ${s.kind}`;$('visualTitle').textContent=s.visual;$('scaleName').textContent=s.scale;$('detailKicker').textContent='GENAU HINSEHEN';$('detailTitle').textContent=s.detail;$('viewNumber').textContent='0'+(n+1);$('viewTitle').textContent=s.title;$('viewText').textContent=s.text;$('takeaway').textContent=s.take;$('question').textContent=s.question;$('answer').textContent=s.answer;$('caption').textContent=s.caption;$('detailNote').textContent=s.note;$('sceneSource').textContent=s.source;$('check').open=false;$('tissue').setAttribute('aria-label',s.visual+' '+s.caption);$('detail').setAttribute('aria-label',s.detail+'. '+s.note);document.querySelectorAll('[data-view]').forEach((b,i)=>{if(i===n)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});}
 $('comptonControls').hidden=n!==1;$('chemControls').hidden=n!==2;$('reactionControls').hidden=n!==3;$('equationPanel').hidden=n<2;$('film').classList.toggle('no-labels',!$('labels').checked);$('next').disabled=n===3;
 [field,compton,chemistry,reactions][n]();$('clock').textContent=clock(time)+' / '+clock(duration);$('timeline').value=time;
}
function status(s){$('playerStatus').textContent=s;}
function setPlaying(value){playing=value;last=0;$('play').textContent=value?'Ⅱ Anhalten':time>=duration?'↺ Erneut abspielen':'▶ Fortsetzen';$('play').setAttribute('aria-label',value?'Animation anhalten':'Animation abspielen');if(value&&!raf)raf=requestAnimationFrame(tick);}
function seek(t){setPlaying(false);time=cl(Number(t),0,duration);render();status('Pausiert · '+scenes[M.scene(time)].nav+'.');}
function tick(ts){raf=0;if(!playing)return;if(!last)last=ts;const dt=Math.min((ts-last)/1000,.12);last=ts;const next=Math.min(duration,time+dt*Number($('speed').value));const boundary=starts.find(x=>x>time&&x<=next);if(boundary!==undefined&&$('pauseBetween').checked){time=boundary;setPlaying(false);status('Neue Ansicht · '+scenes[M.scene(time)].nav+'. Mit Fortsetzen abspielen.');}else{time=next;if(time>=duration){setPlaying(false);status('Phase 03 abgeschlossen. Als Nächstes: DNA-Schäden, Reparatur und mögliche Zellfolgen.');}}if(ts-frame>32||!playing){render();frame=ts;}if(playing)raf=requestAnimationFrame(tick);}
$('views').innerHTML=scenes.map((s,i)=>`<button type="button" data-view="${i}"><small>0${i+1} · ${clock(starts[i])}</small>${s.nav}</button>`).join('');$('views').onclick=e=>{const b=e.target.closest('[data-view]');if(b)seek(starts[Number(b.dataset.view)]);};
$('play').onclick=()=>{if(playing){setPlaying(false);status('Pausiert.');return;}if(time>=duration){time=0;render();}setPlaying(true);status('Animation läuft · stark gestreckte, didaktisch gewählte Filmzeit.');};$('restart').onclick=()=>seek(0);$('next').onclick=()=>seek(starts[Math.min(3,current+1)]);$('timeline').oninput=e=>seek(e.target.value);$('labels').onchange=render;
function changeCompton(){energy=Number($('photonEnergy').value);angle=Number($('angle').value);seek(38);status('Compton-Einzelereignis geändert · Film pausiert. Energien und Winkel sind gekoppelt.');}
$('angle').oninput=changeCompton;$('photonEnergy').onchange=changeCompton;
document.querySelectorAll('[data-chem]').forEach(b=>b.onclick=()=>{seek([45,55,66][Number(b.dataset.chem)]);status('Teilschritt bereit · mit Fortsetzen die Veränderung ansehen.');});
document.querySelectorAll('[data-reaction]').forEach(b=>b.onclick=()=>{reaction=b.dataset.reaction;document.querySelectorAll('[data-reaction]').forEach(v=>v.setAttribute('aria-pressed',String(v.dataset.reaction===reaction)));seek(96);status('Alternative Reaktion gewählt · Ergebnis gezeigt. Zum Verfolgen „Gewählte Reaktion abspielen“ wählen.');});$('replayReaction').onclick=()=>{seek(76);setPlaying(true);status('Gewählte Reaktion läuft.');};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if($('film').requestFullscreen)await $('film').requestFullscreen();else status('Großansicht wird von diesem Browser nicht unterstützt.');}catch{status('Großansicht ist hier nicht verfügbar.');}};document.addEventListener('fullscreenchange',()=>{$('fullscreen').textContent=document.fullscreenElement?'⛶ Verkleinern':'⛶ Großansicht';});document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing){setPlaying(false);status('Pausiert, weil die Seite im Hintergrund ist.');}});
const view=Number(new URLSearchParams(location.search).get('view'));if(Number.isInteger(view)&&view>=0&&view<4)time=starts[view];render();if(matchMedia('(prefers-reduced-motion: reduce)').matches)status('Startbereit · reduzierte Bewegung erkannt. Keine automatische Wiedergabe.');
window.linacPhase3={renderAt:seek,getState:()=>({time,playing,scene:current,energy,angle,reaction,compton:M.compton(energy,angle),chemistry:M.chemistry(time)})};
})();
